def get_divs(n):
    divs = set()
    for i in range(2, int(n**0.5) + 1):
        if n % i == 0:
            divs.add(i)
            divs.add(n // i)
    return sorted(divs)

count = 0
n = 500001
while count < 5:
    d = get_divs(n)
    if d:
        min_d = d[0]
        max_d = d[-1]
        s = min_d + max_d
        if s % 17 == 0:
            print(n, s)
            count += 1
    n += 1
